def solve_m2(a1):
    # Calculate a2: a2 = 335*(a1 - 1) / (328*a1 - 335)
    numerator = 335 * (a1 - 1)
    denominator = 328 * a1 - 335

    if denominator <= 0:
        return None # Should not happen for a1 >= 2

    if numerator % denominator == 0:
        a2 = numerator // denominator
        if a2 > 0 and a2 != a1:
            return a2
        else:
            return None
    else:
        return None

# Check a1 from 2 up to 50
results = {}
for a1 in range(2, 51):
    a2 = solve_m2(a1)
    if a2 is not None:
        results[a1] = a2

print(f"Found pairs (a1, a2): {results}")
